<?php
$labels=['verified'=>'Verified','not_enrolled'=>'Not enrolled','student_not_found'=>'Student not found','invalid_request'=>'Invalid request','unauthorized'=>'Unauthorized','pending'=>'Pending','under_review'=>'Under review','resolved'=>'Resolved','rejected'=>'Rejected'];
$colors=['verified'=>'#228052','not_enrolled'=>'#a66a18','student_not_found'=>'#bd4747','invalid_request'=>'#6d7291','unauthorized'=>'#7752a1','pending'=>'#ce8c18','under_review'=>'#417ab1','resolved'=>'#228052','rejected'=>'#bd4747'];
$donut=static function(array $counts) use ($labels,$colors): void { $total=array_sum($counts); if(!$total){echo '<p class="empty">No records yet.</p>';return;} $position=0; $segments=[]; foreach($counts as $key=>$count){if(!$count)continue;$next=$position+$count/$total*100;$segments[]=($colors[$key]??'#68776c').' '.round($position,4).'% '.round($next,4).'%';$position=$next;} ?>
<div class="records-donut-layout"><div class="records-donut" role="img" aria-label="<?= (int)$total ?> total records" style="background:conic-gradient(<?= esc(implode(',',$segments),'attr') ?>)"><div><strong><?= (int)$total ?></strong><span>Total</span></div></div><ul class="records-legend"><?php foreach($counts as $key=>$count): ?><li><span class="legend-dot" style="background:<?= esc($colors[$key]??'#68776c','attr') ?>"></span><span><?= esc($labels[$key]??ucwords(str_replace('_',' ',$key))) ?></span><strong><?= (int)$count ?></strong><small><?= number_format($count/$total*100,1) ?>%</small></li><?php endforeach ?></ul></div><?php };
$formatTime=static fn($value)=>(new DateTimeImmutable($value,new DateTimeZone('UTC')))->setTimezone(new DateTimeZone('Asia/Manila'))->format('M j, Y, g:i A');
$palette=['#26734d','#c89a13','#5684a1','#8b6da2','#bf7860','#667b61'];
$programColors=['Information Technology'=>'#26734d','Computer Science'=>'#c89a13','Computer Engineering'=>'#5684a1','Civil Engineering'=>'#9168a5','Mechanical Engineering'=>'#bf7860','Electrical Engineering'=>'#667b61','Electronics Engineering'=>'#b85e83'];
$programMax=max([1,...array_map(static fn($r)=>(int)$r['total'],$programDistribution)]);
$trendMax=max(1,...array_map(static fn($r)=>(int)$r['total'],array_values($trend))); $number=count($trend); $points=['total'=>[],'verified'=>[]]; $i=0;
foreach($trend as $date=>$values){$x=55+($number>1?$i*910/($number-1):0);foreach(['total','verified'] as $series)$points[$series][]=round($x,2).','.round(150-$values[$series]/$trendMax*120,2);$i++;}
?>
