</div>
<div class="records-trend-program-grid">
<section class="overview-card trend-card"><header><div><h2>Verification activity trends</h2><p class="overview-caption">Daily events in Asia/Manila</p></div><form method="get" action="<?= site_url('admin/dashboard') ?>" class="trend-filter"><label for="days">Date range</label><select id="days" name="days"><?php foreach([7,30,90] as $range): ?><option value="<?= $range ?>" <?= $days===$range?'selected':'' ?>>Last <?= $range ?> days</option><?php endforeach ?></select><button type="submit">Apply</button></form></header>
<div class="trend-legend"><span><i style="background:#c89a13"></i>Total verification events</span><span><i style="background:#228052"></i>Successful verifications</span></div><?php if(array_sum(array_column($trend,'total'))===0): ?><p class="empty">No verification activity in this period.</p><?php else: ?><div class="trend-chart"><svg viewBox="0 0 1000 180" role="img" aria-label="Daily verification event counts for the last <?= (int)$days ?> days"><line x1="55" y1="150" x2="965" y2="150" stroke="#ccd8cf"/><text x="45" y="154" text-anchor="end">0</text><text x="45" y="34" text-anchor="end"><?= (int)$trendMax ?></text><polyline points="<?= esc(implode(' ',$points['total']),'attr') ?>" fill="none" stroke="#c89a13" stroke-width="3"/><polyline points="<?= esc(implode(' ',$points['verified']),'attr') ?>" fill="none" stroke="#228052" stroke-width="3"/><?php $i=0; foreach($trend as $date=>$values): $x=55+($number>1?$i*910/($number-1):0); ?><circle cx="<?= round($x,2) ?>" cy="<?= round(150-$values['total']/$trendMax*120,2) ?>" r="4" fill="#c89a13"><title><?= esc($date) ?>: <?= (int)$values['total'] ?> total, <?= (int)$values['verified'] ?> verified</title></circle><?php if($i===0 || $i===$number-1 || $i===(int)floor(($number-1)/2)): ?><text x="<?= round($x,2) ?>" y="175" text-anchor="<?= $i===0?'start':($i===$number-1?'end':'middle') ?>"><?= esc((new DateTimeImmutable($date))->format('M j')) ?></text><?php endif ?><?php $i++; endforeach ?></svg><ul class="sr-only"><?php foreach($trend as $date=>$values): ?><li><?= esc($date) ?>: <?= (int)$values['total'] ?> total, <?= (int)$values['verified'] ?> verified</li><?php endforeach ?></ul></div><?php endif ?></section>
<section class="overview-card"><h2>Students by program</h2><p class="overview-caption">Number of student records</p><?php if($programDistribution): ?><div class="program-chart" role="img" aria-label="Student counts by program"><ul><?php foreach($programDistribution as $row): $color=$programColors[$row['program']]??$palette[abs(crc32($row['program']))%count($palette)]; ?><li><span><?= esc($row['program']) ?></span><div class="program-chart-bar"><span style="width:<?= round((int)$row['total']/$programMax*100,2) ?>%;background:<?= esc($color,'attr') ?>"></span></div><strong><?= (int)$row['total'] ?></strong></li><?php endforeach ?></ul><div class="program-axis"><span>0</span><span><?= (int)$programMax ?></span></div></div><?php else: ?><p class="empty">No student records yet.</p><?php endif ?></section>
</div>
