<section class="overview-card"><header><h2>Recent assistance requests</h2><a class="overview-view-all" href="<?= site_url('admin/verification-management?tab=requests') ?>">View All <span class="material-symbols-outlined">arrow_forward</span></a></header><?php if($requestCounts['pending']): ?><p class="records-request-notice"><?= (int)$requestCounts['pending'] ?> request<?= $requestCounts['pending']===1?'':'s' ?> awaiting review.</p><?php endif ?><?php if($recentRequests): ?><div class="table-wrap"><table><thead><tr><th>Request</th><th>Student</th><th>Status</th><th>Submitted (Manila)</th></tr></thead><tbody><?php foreach($recentRequests as $request): ?><tr><td><a href="<?= site_url('admin/verification-requests/'.$request['id']) ?>">#<?= (int)$request['id'] ?></a></td><td><?= esc($request['full_name']) ?></td><td><span class="status-badge <?= esc($request['status'],'attr') ?>"><?= esc($labels[$request['status']]??$request['status']) ?></span></td><td><?= esc($formatTime($request['created_at'])) ?></td></tr><?php endforeach ?></tbody></table></div><?php else: ?><p class="empty">No assistance requests yet.</p><?php endif ?></section></div>
</div>
